(5820046, 848219, 66384, '<td valign="top">I love the colors and reflection in the bubble.</td>', 'I love the colors and reflection in the bubble.', '2010-01-20 17:06:12.000000', NULL, 1),
(5820055, 848061, 66384, '<td valign="top">The colors are sublime!</td>', 'The colors are sublime!', '2010-01-20 17:10:10.000000', NULL, 1),
(5820068, 847686, 66384, '<td valign="top">So cute.</td>', 'So cute.', '2010-01-20 17:14:53.000000', NULL, 1),
