INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5820381, 848276, 327, '<td valign="top">lol I didn''t think to try that! Great creative thinking.</td>', 'lol I didn''t think to try that! Great creative thinking.', '2010-01-20 20:05:05.000000', NULL, 1),
(5820384, 847767, 327, '<td valign="top">Pretty carmel color. Nice work.</td>', 'Pretty carmel color. Nice work.', '2010-01-20 20:06:01.000000', NULL, 1),
(5820390, 848094, 327, '<td valign="top">Goog looking shot and nice bubbles.</td>', 'Goog looking shot and nice bubbles.', '2010-01-20 20:08:42.000000', NULL, 1),
(5820392, 848126, 327, '<td valign="top">LOL it''s a bubble!! Creative.</td>', 'LOL it''s a bubble!! Creative.', '2010-01-20 20:09:28.000000', NULL, 1),
(5820393, 846895, 327, '<td valign="top">9 from me. Very good.</td>', '9 from me. Very good.', '2010-01-20 20:10:03.000000', NULL, 1),
(5820396, 848148, 327, '<td valign="top">Neat colors, wonderful bubbles.</td>', 'Neat colors, wonderful bubbles.', '2010-01-20 20:11:00.000000', NULL, 1),
(5820398, 847311, 327, '<td valign="top">Gumby your such a flirt! lol cute.</td>', 'Gumby your such a flirt! lol cute.', '2010-01-20 20:12:17.000000', NULL, 1),
(5820400, 847326, 327, '<td valign="top">Poor dog you kept him up! Beautiful lighting, focus. WONDERFUL bubbles.</td>', 'Poor dog you kept him up! Beautiful lighting, focus. WONDERFUL bubbles.', '2010-01-20 20:13:36.000000', NULL, 1),
(5820431, 847569, 111808, '<td valign="top">The blue tones of the geyser bubble are quite beautiful against the dark and steamy natural landscape. The sky reflections in the waterpools adds wonderful textures to this shot as well. An interesting take on the challenge interpretation.</td>', 'The blue tones of the geyser bubble are quite beautiful against the dark and steamy natural landscape. The sky reflections in the waterpools adds wonderful textures to this shot as well. An interesting take on the challenge interpretation.', '2010-01-20 20:49:00.000000', NULL, 1),
(5820435, 847311, 111808, '<td valign="top">Then again, Gumby''s right hand is in a most interesting position relative to the bubbles. Good for a laugh and Barbie looks quite different with a celebrity tan.</td>', 'Then again, Gumby''s right hand is in a most interesting position relative to the bubbles. Good for a laugh and Barbie looks quite different with a celebrity tan.', '2010-01-20 20:51:28.000000', NULL, 1),
(5820439, 848245, 111808, '<td valign="top">The expression on the face of the dog is absolutely priceless.</td>', 'The expression on the face of the dog is absolutely priceless.', '2010-01-20 20:52:38.000000', NULL, 1),
(5820442, 847516, 111808, '<td valign="top">Love the flowing rainbow colours in this and it really does resemble a planet with how it is captured. The black background really sets it off nicely as well.</td>', 'Love the flowing rainbow colours in this and it really does resemble a planet with how it is captured. The black background really sets it off nicely as well.', '2010-01-20 20:54:25.000000', NULL, 1),
(5820450, 848266, 111808, '<td valign="top">Absolutely stunning seascape. It must have been a windy day as well to generate all that froth and foam.  The harsh and jagged texture of the snag and the beach debris brought in by a former storm adds wonderful contrast to this as does the diagonal of the trees and the landscape in the far distance and even the clouds have conformed to complete it with their cottonpuffs.</td>', 'Absolutely stunning seascape. It must have been a windy day as well to generate all that froth and foam.  The harsh and jagged texture of the snag and the beach debris brought in by a former storm adds wonderful contrast to this as does the diagonal of the trees and the landscape in the far distance and even the clouds have conformed to complete it with their cottonpuffs.', '2010-01-20 21:00:36.000000', NULL, 1),
(5820454, 848125, 111808, '<td valign="top">This bubble is floating away, softly, quietly, with the most beautiful reflections inside...This photograph is serene, tranquil, beautiful.</td>', 'This bubble is floating away, softly, quietly, with the most beautiful reflections inside...This photograph is serene, tranquil, beautiful.', '2010-01-20 21:03:25.000000', NULL, 1),
(5820458, 848148, 111808, '<td valign="top">The bubble on the top looks like an eyeball, the one on the very bottom looks like a rainbow peacock feather. Nice colours in this group of 6 conjoined globules.</td>', 'The bubble on the top looks like an eyeball, the one on the very bottom looks like a rainbow peacock feather. Nice colours in this group of 6 conjoined globules.', '2010-01-20 21:06:45.000000', NULL, 1),
(5820460, 847257, 111808, '<td valign="top">Gorgeous rainbow colourlines in this set up beautifully with the black background. The diagonal crop makes this superb.</td>', 'Gorgeous rainbow colourlines in this set up beautifully with the black background. The diagonal crop makes this superb.', '2010-01-20 21:09:49.000000', NULL, 1),
(5820461, 848090, 111808, '<td valign="top">Effervescent, delightful, juicy...and GREEN! Kaleidoscopic background is a nice touch.</td>', 'Effervescent, delightful, juicy...and GREEN! Kaleidoscopic background is a nice touch.', '2010-01-20 21:13:00.000000', NULL, 1),
(5820463, 847386, 111808, '<td valign="top">This dual toned photograph is simple yet it is quite powerful. The black surround sets off the orange of the furnace and within there is a beautiful glass creation beginning to shape up. The heat emanating from the kiln is also quite palpable in this capture - outstanding and unusual angle.</td>', 'This dual toned photograph is simple yet it is quite powerful. The black surround sets off the orange of the furnace and within there is a beautiful glass creation beginning to shape up. The heat emanating from the kiln is also quite palpable in this capture - outstanding and unusual angle.', '2010-01-20 21:18:58.000000', NULL, 1),
(5820465, 846895, 111808, '<td valign="top">Well done water bubble - you imparted the sense of otherworldly life in it and in the reflection. Kudos to Cameron for his wonderful films which entertain, make you feel and make you sense something more, as this does.<br/>Beautiful.</td>', 'Well done water bubble - you imparted the sense of otherworldly life in it and in the reflection. Kudos to Cameron for his wonderful films which entertain, make you feel and make you sense something more, as this does.Beautiful.', '2010-01-20 21:21:09.000000', NULL, 1),
(5820470, 847613, 111808, '<td valign="top">This looks inviting. The champagne glass is well lit and has beautiful vertical lines in it. Half a glass with tiny bubbles - is it half full or half empty? Only the viewer can decide.</td>', 'This looks inviting. The champagne glass is well lit and has beautiful vertical lines in it. Half a glass with tiny bubbles - is it half full or half empty? Only the viewer can decide.', '2010-01-20 21:23:34.000000', NULL, 1),
(5820473, 848220, 111808, '<td valign="top">The beauty of the detergent bubbles almost makes the task of washing the dishes an honour rather than a chore. There is so much we miss in the everyday ordinariness of Life because we do not see it - until someone brings it to our awareness and attention once again. Thank you for that looking.</td>', 'The beauty of the detergent bubbles almost makes the task of washing the dishes an honour rather than a chore. There is so much we miss in the everyday ordinariness of Life because we do not see it - until someone brings it to our awareness and attention once again. Thank you for that looking.', '2010-01-20 21:27:30.000000', NULL, 1),
(5820480, 848219, 111808, '<td valign="top">Concentric circular ripples growing ever wider, small planet reflection in the centre, blues, greens, fragility - all echoing themes. Simple subject here, masterful execution of many melodious philosophies.</td>', 'Concentric circular ripples growing ever wider, small planet reflection in the centre, blues, greens, fragility - all echoing themes. Simple subject here, masterful execution of many melodious philosophies.', '2010-01-20 21:34:05.000000', NULL, 1),
(5820481, 848221, 111808, '<td valign="top">Love the translucent green of the juice sacks of this lime enhanced and in some cases even magnified by the tiny bubbles. Looks quite refreshing.</td>', 'Love the translucent green of the juice sacks of this lime enhanced and in some cases even magnified by the tiny bubbles. Looks quite refreshing.', '2010-01-20 21:37:22.000000', NULL, 1),
(5820485, 847396, 111808, '<td valign="top">Darkly disturbing in a most deliberate fashion, a dirty separated hand with the wedding ring still on it being delivered, securely packed and wrapped in bubblewrap so as not to (presumably) damage it any more. One has to wonder about the sender of such an item; the recipient''s reaction could perhaps be more easily judged. Different entry, definitely.</td>', 'Darkly disturbing in a most deliberate fashion, a dirty separated hand with the wedding ring still on it being delivered, securely packed and wrapped in bubblewrap so as not to (presumably) damage it any more. One has to wonder about the sender of such an item; the recipient''s reaction could perhaps be more easily judged. Different entry, definitely.', '2010-01-20 21:43:22.000000', NULL, 1),
(5820492, 847171, 111808, '<td valign="top">Liquid low key exposure makes this darkly beautiful. Understated but quite effective and beautiful as well.</td>', 'Liquid low key exposure makes this darkly beautiful. Understated but quite effective and beautiful as well.', '2010-01-20 21:46:28.000000', NULL, 1),
(5820497, 847771, 111808, '<td valign="top">The colours and curves in this are beautiful, flowing, liquid.</td>', 'The colours and curves in this are beautiful, flowing, liquid.', '2010-01-20 21:50:12.000000', NULL, 1),
(5820499, 848057, 111808, '<td valign="top">Cute child and a delightfully HUGE bubble which has the most perfect landscape doubly echoing within it. This evokes a feeling of pure wonder and joy.</td>', 'Cute child and a delightfully HUGE bubble which has the most perfect landscape doubly echoing within it. This evokes a feeling of pure wonder and joy.', '2010-01-20 21:53:12.000000', NULL, 1),
(5820504, 847001, 111808, '<td valign="top">These bubbles glitter which makes them beautiful in and of themselves displaying their colours. The black background just sets this off by focusing the vision directly to the centre.</td>', 'These bubbles glitter which makes them beautiful in and of themselves displaying their colours. The black background just sets this off by focusing the vision directly to the centre.', '2010-01-20 21:56:48.000000', NULL, 1),
